package com.amit.headroom;
import android.content.*;import android.widget.*;import org.json.*;import java.util.*;
public class HeadRoomWidgetService extends RemoteViewsService{public RemoteViewsFactory onGetViewFactory(Intent i){return new Factory(getApplicationContext());}static class Factory implements RemoteViewsFactory{final Context c;JSONArray tasks=new JSONArray();Factory(Context c){this.c=c;}public void onCreate(){}public void onDataSetChanged(){try{String json=c.getSharedPreferences("HeadRoomWidget",MODE_PRIVATE).getString("tasks","[]");tasks=new JSONArray(json);}catch(Exception e){tasks=new JSONArray();}}public void onDestroy(){}public int getCount(){return tasks.length();}public RemoteViews getViewAt(int p){try{JSONObject t=tasks.getJSONObject(p);RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.headroom_widget_task);boolean done=t.optBoolean("done");v.setTextViewText(R.id.taskCheck,done?"✓":"○");v.setTextViewText(R.id.taskTitle,t.optString("text"));String due=t.optString("due");String priority=t.optString("priority","medium").toUpperCase(Locale.ROOT);String tag=t.optString("tag");v.setTextViewText(R.id.taskMeta,(due.isEmpty()?"No due date":due)+"  •  "+priority+(tag.isEmpty()?"":"  •  "+tag));return v;}catch(Exception e){return null;}}public RemoteViews getLoadingView(){return null;}public int getViewTypeCount(){return 1;}public long getItemId(int p){return p;}public boolean hasStableIds(){return false;}}}